--
-- Table structure for table `hocky`
--

CREATE TABLE `hocky` (
  `HocKyID` int(11) NOT NULL,
  `NamHocID` int(11) DEFAULT NULL,
  `TenHocKy` varchar(50) DEFAULT NULL,
  `LoaiHocKy` enum('HK1','HK2','He') DEFAULT NULL,
